import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;

public class FastDateFormat_getDateTimeInstance_TriageGen0Test {









    @Test
    public void testGetDateTimeInstance_DifferentCombinations() {
        int dateStyle = Calendar.LONG;
        int timeStyle = Calendar.LONG;
        TimeZone tz1 = TimeZone.getTimeZone("GMT");
        TimeZone tz2 = TimeZone.getTimeZone("EST");
        Locale loc1 = Locale.ENGLISH;
        Locale loc2 = Locale.GERMAN;

        FastDateFormat f1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz1, loc1);
        FastDateFormat f2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz2, loc1);
        FastDateFormat f3 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, tz1, loc2);

        assertNotNull(f1);
        assertNotNull(f2);
        assertNotNull(f3);

        // Ensure they are distinct instances due to different keys
        org.junit.Assert.assertNotSame(f1, f2);
        org.junit.Assert.assertNotSame(f1, f3);
    }
}
